import type { ComponentProps, ReactNode, RefObject } from "react"
import { cn } from "@/lib/utils"
import type { ScrollSpyRoot } from "@/registry/gooseui/hooks/use-scroll-spy"
import { TocScrollspySpy } from "@/registry/gooseui/ui/toc-scrollspy.client"

export type TocScrollspyItem = {
  id: string
  title: ReactNode
  /** Heading level, e.g. 2 for h2. Deeper levels are nested. */
  level?: number
}

export type TocScrollspyProps = Omit<ComponentProps<"nav">, "title"> & {
  /** Items to render on the server. When omitted, headings are collected on the client with `selector`. */
  items?: TocScrollspyItem[]
  /** CSS selector for headings to collect, e.g. "h2, h3". */
  selector?: string
  /** Where to look for headings. Defaults to the document. */
  container?: HTMLElement | null | RefObject<HTMLElement | null>
  /** Scroll container. Defaults to the window. */
  root?: ScrollSpyRoot
  /** Activation line and scroll offset in pixels (e.g. sticky header height). */
  offset?: number
  /** Stick to the top of the scroll area. */
  sticky?: boolean
  /** Write the active id to the URL hash on click. */
  updateHash?: boolean
  /** Heading shown above the list. Pass null to hide it. */
  title?: ReactNode
  /** Classes for the scrollable list wrapper, e.g. "max-h-[70vh] overflow-y-auto". */
  listClassName?: string
  /** Extra content under the list, separated by a border (e.g. an edit link). */
  footer?: ReactNode
  labels?: { nav?: string; title?: string }
  onNavigate?: (id: string) => void
}

type TreeNode = TocScrollspyItem & { children: TreeNode[] }

function buildTree(items: TocScrollspyItem[]): TreeNode[] {
  const roots: TreeNode[] = []
  const stack: TreeNode[] = []
  const base = Math.min(...items.map((i) => i.level ?? 2))
  for (const item of items) {
    const node: TreeNode = { ...item, level: item.level ?? base, children: [] }
    while (
      stack.length &&
      (stack[stack.length - 1].level ?? base) >= (node.level ?? base)
    ) {
      stack.pop()
    }
    const parent = stack[stack.length - 1]
    if (parent) parent.children.push(node)
    else roots.push(node)
    stack.push(node)
  }
  return roots
}

const linkClass =
  "block cursor-pointer rounded-sm text-[0.8rem] leading-snug text-muted-foreground no-underline transition-colors outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=location]:font-medium aria-[current=location]:text-foreground"

// Nesting indent: 0, 1rem, 1.5rem, ...
const indent = (depth: number) => (depth === 0 ? 0 : 0.5 + depth * 0.5)

function renderNodes(nodes: TreeNode[], depth: number): ReactNode {
  return (
    <ul className={cn("space-y-2", depth > 0 && "mt-2")}>
      {nodes.map((node) => (
        <li key={node.id}>
          <a
            href={`#${node.id}`}
            data-toc-id={node.id}
            style={{ paddingLeft: `${indent(depth)}rem` }}
            className={linkClass}
          >
            {node.title}
          </a>
          {node.children.length > 0 && renderNodes(node.children, depth + 1)}
        </li>
      ))}
    </ul>
  )
}

/**
 * Table of contents. The list is server-rendered anchor links that work
 * without JavaScript; a small client island highlights the active section
 * (exactly one at a time) and scrolls smoothly with an offset.
 */
export function TocScrollspy({
  items,
  selector,
  container,
  root,
  offset = 16,
  sticky = true,
  updateHash = true,
  title,
  listClassName,
  footer,
  labels,
  onNavigate,
  className,
  style,
  ...props
}: TocScrollspyProps) {
  const heading =
    title === undefined ? (labels?.title ?? "On this page") : title

  return (
    <nav
      data-toc-scrollspy=""
      aria-label={labels?.nav ?? "Table of contents"}
      className={cn(sticky && "sticky top-4 self-start", className)}
      style={sticky ? { top: offset, ...style } : style}
      {...props}
    >
      {heading !== null && (
        <p className="mb-2 text-sm font-medium">{heading}</p>
      )}
      <div data-toc-list="" className={cn("py-1", listClassName)}>
        {items?.length ? renderNodes(buildTree(items), 0) : null}
        <TocScrollspySpy
          ids={items ? items.map((i) => i.id) : undefined}
          selector={items ? undefined : selector}
          container={container}
          root={root}
          offset={offset}
          updateHash={updateHash}
          onNavigate={onNavigate}
        />
      </div>
      {footer && <div className="mt-8 border-t pt-4">{footer}</div>}
    </nav>
  )
}

"use client"

import { type RefObject, useEffect, useMemo, useRef, useState } from "react"
import {
  type ScrollSpyRoot,
  useScrollSpy,
} from "@/registry/gooseui/hooks/use-scroll-spy"

type Collected = { id: string; title: string; level: number }

export type TocScrollspySpyProps = {
  /** Ids of server-rendered links. Ignored when `selector` is set */
  ids?: string[]
  selector?: string
  container?: HTMLElement | null | RefObject<HTMLElement | null>
  root?: ScrollSpyRoot
  offset: number
  updateHash: boolean
  onNavigate?: (id: string) => void
}

function resolveEl(
  value: HTMLElement | null | undefined | RefObject<HTMLElement | null>,
): HTMLElement | null {
  if (!value) return null
  if (value instanceof HTMLElement) return value
  return value.current
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "")
}

/**
 * Client part of TocScrollspy: highlights the active link and makes
 * clicks scroll smoothly with an offset. The links
 * themselves are plain anchors and work without it.
 */
export function TocScrollspySpy({
  ids: idsProp,
  selector,
  container,
  root,
  offset,
  updateHash,
  onNavigate,
}: TocScrollspySpyProps) {
  const anchorRef = useRef<HTMLSpanElement>(null)
  const [collected, setCollected] = useState<Collected[]>([])

  // Selector mode: collect headings and render the list on the client
  useEffect(() => {
    if (!selector) return
    const scope = resolveEl(container) ?? document
    const read = () => {
      const next: Collected[] = []
      for (const el of scope.querySelectorAll<HTMLElement>(selector)) {
        const title = el.textContent?.trim() ?? ""
        if (!el.id) {
          const base = slugify(title) || "section"
          let id = base
          for (let n = 2; document.getElementById(id); n++) id = `${base}-${n}`
          el.id = id
        }
        const level = /^H([1-6])$/.exec(el.tagName)?.[1]
        next.push({ id: el.id, title, level: level ? Number(level) : 2 })
      }
      setCollected((prev) =>
        prev.length === next.length &&
        prev.every((p, i) => p.id === next[i].id && p.title === next[i].title)
          ? prev
          : next,
      )
    }
    read()
    const mo = new MutationObserver(read)
    mo.observe(scope, { childList: true, subtree: true, characterData: true })
    return () => mo.disconnect()
  }, [selector, container])

  const ids = useMemo(
    () => (selector ? collected.map((c) => c.id) : (idsProp ?? [])),
    [selector, collected, idsProp],
  )
  const spied = useScrollSpy(ids, { root, offset: offset + 8 })

  // While a click-triggered smooth scroll runs, keep the clicked item active
  const [pinned, setPinned] = useState<string | null>(null)
  const activeId = pinned ?? spied

  useEffect(() => {
    if (!pinned) return
    const target: HTMLElement | Window = resolveEl(root) ?? window
    let timer = window.setTimeout(() => setPinned(null), 1200)
    const release = () => {
      window.clearTimeout(timer)
      timer = window.setTimeout(() => setPinned(null), 80)
    }
    target.addEventListener("scrollend", release)
    return () => {
      window.clearTimeout(timer)
      target.removeEventListener("scrollend", release)
    }
  }, [pinned, root])

  // aria-current marks the single active link
  useEffect(() => {
    const nav = anchorRef.current?.closest("[data-toc-scrollspy]")
    if (!nav) return
    for (const link of nav.querySelectorAll<HTMLElement>("[data-toc-id]")) {
      if (link.dataset.tocId === activeId) {
        link.setAttribute("aria-current", "location")
      } else link.removeAttribute("aria-current")
    }
  }, [activeId, ids])

  // Smooth scroll with offset, focus move and optional hash update
  useEffect(() => {
    const nav = anchorRef.current?.closest("[data-toc-scrollspy]")
    if (!nav) return
    const onClick = (event: Event) => {
      const e = event as MouseEvent
      const link = (e.target as HTMLElement).closest<HTMLElement>(
        "[data-toc-id]",
      )
      if (!link || e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0)
        return
      const id = link.dataset.tocId ?? ""
      const el = document.getElementById(id)
      if (!el) return
      e.preventDefault()
      const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches
      const behavior: ScrollBehavior = reduce ? "auto" : "smooth"
      const rootEl = resolveEl(root)
      if (rootEl) {
        const top =
          el.getBoundingClientRect().top -
          rootEl.getBoundingClientRect().top +
          rootEl.scrollTop -
          offset
        rootEl.scrollTo({ top, behavior })
      } else {
        const top = el.getBoundingClientRect().top + window.scrollY - offset
        window.scrollTo({ top, behavior })
      }
      if (updateHash) history.replaceState(history.state, "", `#${id}`)
      if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "-1")
      el.focus({ preventScroll: true })
      setPinned(id)
      onNavigate?.(id)
    }
    nav.addEventListener("click", onClick)
    return () => nav.removeEventListener("click", onClick)
  }, [root, offset, updateHash, onNavigate])

  if (!selector) return <span ref={anchorRef} hidden />

  const base = Math.min(...collected.map((c) => c.level))
  return (
    <>
      <span ref={anchorRef} hidden />
      <ul className="space-y-2">
        {collected.map((item) => (
          <li key={item.id}>
            <a
              href={`#${item.id}`}
              data-toc-id={item.id}
              style={{
                paddingLeft: `${item.level === base ? 0 : 0.5 + (item.level - base) * 0.5}rem`,
              }}
              className="block cursor-pointer rounded-sm text-[0.8rem] leading-snug text-muted-foreground no-underline transition-colors outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=location]:font-medium aria-[current=location]:text-foreground"
            >
              {item.title}
            </a>
          </li>
        ))}
      </ul>
    </>
  )
}
